36	const outputToSimpleString = (output: EvaluateTableOutput) => {
37	  const passFailText = output.pass
38	    ? '[PASS]'
39	    : output.failureReason === ResultFailureReason.ASSERT
40	      ? '[FAIL]'
41	      : '[ERROR]';
42	  const namedScoresText = Object.entries(output.namedScores)
43	    .map(([name, value]) => `${name}: ${value?.toFixed(2)}`)
44	    .join(', ');
45	  const scoreText =
46	    namedScoresText.length > 0
47	      ? `(${output.score?.toFixed(2)}, ${namedScoresText})`
48	      : `(${output.score?.toFixed(2)})`;
49	  const gradingResultText = output.gradingResult
50	    ? `${output.pass ? 'Pass' : 'Fail'} Reason: ${output.gradingResult.reason}`
51	    : '';
52	  return dedent`
53	      ${passFailText} ${scoreText}
54	
55	      ${output.text}
56	
57	      ${gradingResultText}
58	    `.trim();
59	};
