69	function projectTracesForOutput(traces: NonNullable<OutputFile['traces']>) {
70	  const shouldStripMetadata = getEnvBool('PROMPTFOO_STRIP_METADATA', false);
71	  const shouldStripPromptText = getEnvBool('PROMPTFOO_STRIP_PROMPT_TEXT', false);
72	  const shouldStripResponseOutput = getEnvBool('PROMPTFOO_STRIP_RESPONSE_OUTPUT', false);
73	  const shouldStripTestVars = getEnvBool('PROMPTFOO_STRIP_TEST_VARS', false);
74	
75	  if (
76	    !shouldStripMetadata &&
77	    !shouldStripPromptText &&
78	    !shouldStripResponseOutput &&
79	    !shouldStripTestVars
80	  ) {
81	    return traces;
82	  }
83	
84	  return traces.map((trace) => {
85	    let projectedTrace = trace;
86	    if (shouldStripMetadata) {
87	      const { metadata: _metadata, ...traceWithoutMetadata } = trace;
88	      projectedTrace = traceWithoutMetadata;
89	    } else if (shouldStripTestVars && trace.metadata && 'vars' in trace.metadata) {
90	      const { metadata: traceMetadata, ...traceWithoutMetadata } = trace;
91	      const { vars: _vars, ...metadata } = traceMetadata;
92	      projectedTrace = {
93	        ...traceWithoutMetadata,
94	        ...(Object.keys(metadata).length > 0 && { metadata }),
95	      };
96	    }
97	
98	    if (!shouldStripPromptText && !shouldStripResponseOutput) {
99	      return projectedTrace;
100	    }
101	
102	    return {
103	      ...projectedTrace,
104	      spans: projectedTrace.spans.map((span) => {
105	        if (!span.attributes) {
106	          return span;
107	        }
108	
109	        const projectedAttributes = { ...span.attributes };
110	        if (shouldStripPromptText) {
111	          delete projectedAttributes[PromptfooAttributes.REQUEST_BODY];
112	        }
113	        if (shouldStripResponseOutput) {
114	          delete projectedAttributes[PromptfooAttributes.RESPONSE_BODY];
115	        }
116	
117	        const { attributes: _attributes, ...projectedSpan } = span;
118	        return {
119	          ...projectedSpan,
120	          ...(Object.keys(projectedAttributes).length > 0 && {
121	            attributes: projectedAttributes,
122	          }),
123	        };
124	      }),
125	    };
126	  });
127	}
