129	function resultsForMediaExportScan(results: OutputFile['results']): unknown {
130	  if (!getEnvBool('PROMPTFOO_STRIP_RESPONSE_OUTPUT', false)) {
131	    return results;
132	  }
133	
134	  return {
135	    ...results,
136	    results: results.results.map((result) => {
137	      const response = (result as { response?: { metadata?: Record<string, unknown> } }).response;
138	      if (!response?.metadata || !('blobUris' in response.metadata)) {
139	        return result;
140	      }
141	
142	      const { metadata: responseMetadata, ...projectedResponse } = response;
143	      const { blobUris: _blobUris, ...metadata } = responseMetadata;
144	      return {
145	        ...result,
146	        response: {
147	          ...projectedResponse,
148	          ...(Object.keys(metadata).length > 0 && { metadata }),
149	        },
150	      };
151	    }),
152	  };
153	}
